local eventmanager = (...)local Controls = {}local CONTROLLER_TYPE_GAMEPAD = 0local CONTROLLER_TYPE_TOUCH = 4local BND_IS_TOUCH_CONTROL = "bnd_is_touch_control"local ACT_TOUCH = "act_select_touch_controls"local ACT_CONTROL = "act_select_controller_controls"local EventTypes = eventmanager.FE.FIFA.EventTypesfunction Controls:new(init)  local o = init or {}  setmetatable(o, self)  self.__index = self  o.isInGame = type(o.data) == "table" and o.data.ingame or false  o.services = {    gameState = o.api("GameStateService")  }  o.subControllerType = nil  o.controllerType = CONTROLLER_TYPE_TOUCH  if o.services.gameState.IsGamepadControllerConnected() then    o.controllerType = CONTROLLER_TYPE_GAMEPAD  end  o.im.Subscribe(BND_IS_TOUCH_CONTROL, function()    o.im.Publish(BND_IS_TOUCH_CONTROL, o.controllerType == CONTROLLER_TYPE_TOUCH)  end  )  o.im.RegisterAction(ACT_TOUCH, function(actionName, id)    o.nav.Event(nil, "evt_select_touch_controls", o.isInGame)  end  )  o.im.RegisterAction(ACT_CONTROL, function(actionName, id)    o.nav.Event(nil, "evt_select_controller_controls", o.isInGame)    if not o.services.gameState.IsGamepadControllerConnected() then      local buttonYes = {        icon = "$FooterIconYes",        label = "Confirm",        clickEvents = {          "evt_hide_popup"        }      }      local popupData = {        title = "Gamepad It's Not Connected",        message = "Settings Controllers",        autoEscape = false,        buttons = {buttonYes}      }      o.nav.Event(nil, "evt_show_popup", popupData)    end  end  )  if o.controllerType == CONTROLLER_TYPE_GAMEPAD then    o.nav.Event(nil, "evt_select_controller_controls", o.isInGame)  else    o.nav.Event(nil, "evt_select_touch_controls", o.isInGame)  end  o.im.Publish(BND_IS_TOUCH_CONTROL, o.controllerType == CONTROLLER_TYPE_TOUCH)  return oendfunction Controls:finalize()  self.im.Unsubscribe(BND_IS_TOUCH_CONTROL)  self.im.UnregisterAction(ACT_TOUCH)  self.im.UnregisterAction(ACT_CONTROL)endreturn Controls